// Why Code: reads the command against the numbered topic list and decides the one change to make (or the reply when nothing changes).
const c = $('When Called By Bot').first().json;
const s = $('Store Settings').first().json;
const kind = c.topic_kind === 'ws' ? 'ws' : 'ds';
const mode = kind === 'ws' ? '7days' : 'today';
const name = kind === 'ws' ? 'weekly searches' : 'daily searches';
const rows = $input.all().flatMap(i => i.json.records || []).filter(r => r.fields.mode === mode)
  .sort((a, b) => String(a.createdTime).localeCompare(String(b.createdTime)));
const planOf = (r) => { try { return (JSON.parse(r.fields.plan || '[]') || []).map(a => a.angle); } catch (e) { return []; } };
const list = () => rows.length ? rows.map((r, i) => `${i + 1}. ${r.fields.active === true ? 'ON' : 'OFF'} ${r.fields.keyword}` + (planOf(r).length ? `\n   angles: ${planOf(r).join('; ')}` : '\n   angles: not written yet (written on the next Monday refresh, or with update)')).join('\n') : `No ${name} yet. Add one: add ${kind} "your topic"`;
const topic = String(c.topic_text || '').replace(/^["'“”‘’]+|["'“”‘’]+$/g, '').trim();
const isQuestion = /^\s*(what|why|how|which|who|whom|whose|when|where|is|are|was|were|does|do|did|can|could|should|will|would)\b/i.test(topic) || /\?\s*$/.test(topic);
const n = Number(c.topic_number || 0);
const row = n >= 1 && n <= rows.length ? rows[n - 1] : null;
const base = { chat_id: c.chat_id, email: c.email, kind, mode, name, keyword: topic, is_question: isQuestion, number: n };
let out;
if (c.topic_action === 'list') out = { route: 'reply', text: `## Your ${name}\n${list()}` };
else if (c.topic_action === 'add' && !topic) out = { route: 'reply', text: `Write the topic after the command, for example: add ${kind} "AI industry news"` };
else if (c.topic_action === 'add' && rows.some(r => String(r.fields.keyword).toLowerCase() === topic.toLowerCase())) { const k = rows.findIndex(r => String(r.fields.keyword).toLowerCase() === topic.toLowerCase());
  out = { route: 'reply', text: `"${topic}" is already number ${k + 1} of your ${name} (${rows[k].fields.active === true ? `ON; to stop it: off ${kind} ${k + 1}` : `OFF; to start it: on ${kind} ${k + 1}`}).` }; }
else if (c.topic_action === 'add') out = { route: 'plan', action: 'add' };
else if (!row) out = { route: 'reply', text: `There is no number ${n || '(missing)'} in your ${name}. Write the number from this list:\n${list()}` };
else if (c.topic_action === 'on' || c.topic_action === 'off') out = { route: 'write', action: c.topic_action, record_id: row.id, keyword: row.fields.keyword };
else if (!topic) out = { route: 'reply', text: `Write the new topic after the number, for example: update ${kind} ${n} "AI industry news"` };
else out = { route: 'plan', action: 'update', record_id: row.id, old_keyword: row.fields.keyword };
return [{ json: { ...base, ...out } }];

// Why Code: one Airtable request for the change: a new row (add), the new topic and plan (update), switched on or off. Added and updated topics are on.
const d = $('Decide Topic Change').first().json;
const s = $('Store Settings').first().json;
const p = $('Plan Topic (via Plan Topic)').isExecuted ? $('Plan Topic (via Plan Topic)').first().json : {};
const now = new Date().toISOString();
const url = `https://api.airtable.com/v0/${s.airtable_base}/${s.keywords_table}`;
const fields = d.action === 'on' || d.action === 'off' ? { active: d.action === 'on' }
  : { keyword: d.keyword, plan: JSON.stringify(p.angles || []), plan_updated: now, active: true, ...(d.action === 'add' ? { mode: d.mode, recipient: d.email } : {}) };
const record = d.action === 'add' ? { fields } : { id: d.record_id, fields };
return [{ json: { method: d.action === 'add' ? 'POST' : 'PATCH', url, body: { records: [record], typecast: true } } }];

// Why Code: the one reply for every path: the list or a usage hint, a plan that failed the check, or what was saved.
const d = $('Decide Topic Change').first().json;
const p = $('Plan Topic (via Plan Topic)').isExecuted ? $('Plan Topic (via Plan Topic)').first().json : null;
const saved = $('Save Topic (Airtable)').isExecuted && !$('Save Topic (Airtable)').first().json.error;
const when = d.mode === '7days' ? 'every Monday at 07:00 (last 7 days, PDF by email)' : 'every day at 07:00 (last 24 hours)';
let text;
if (d.route === 'reply') text = d.text;
else if (p && !p.ok) text = `I could not write a good search plan for "${d.keyword}": ${p.reason || p.error || 'the planner did not answer'}. Nothing changed. Try again, or word the topic differently.`;
else if (!saved) text = `I could not save the change in Airtable. Nothing changed. Try again in a minute.`;
else if (d.action === 'off') text = `OFF: "${d.keyword}". It no longer runs. To start it again: on ${d.kind} ${d.number}`;
else if (d.action === 'on') text = `ON: "${d.keyword}". It runs ${when}. To stop it: off ${d.kind} ${d.number}`;
else text = `${d.action === 'add' ? 'Added' : 'Updated'} and ON: "${d.keyword}"${d.action === 'update' ? ` (was "${d.old_keyword}")` : ''}. It runs ${when}${d.is_question ? '; it is a question, so the answer is also looked up on the web' : ''}.\nSearch angles:\n` + (p.angles || []).map(a => `- ${a.angle}`).join('\n');
return [{ json: { chat_id: d.chat_id, text } }];
